rows[108271]={title={{12,113329314},"영혼 이동"},description={"^seek haven by shifting partially into the elemental planes, reducing damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","영혼 일부를 안전한 정령계로 옮겨 \0312\031 동안 받는 피해를 \0311\031%만큼 감소시킵니다.",{0,1},{1,2}},aura={"^damage taken reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","받는 피해 \0311\031%만큼 감소",{0},{1}}}
rows[108272]={title={{19,1702602505},"늑대 정령 연마"},description={{59,154753927},"늑대 정령으로 변신한 동안 감속 효과를 무시합니다."}}
