rows[108279]={title={{19,264392188},"고요한 마음의 토템"},description={"^summons an air totem with ([%+%-]?%d[%d,.%+%-to –]*) health at the feet of the caster for ([%+%-]?%d[%d,.]* %a+), granting raid members within 30 yards immunity to spellcast interruption and silence effects%.$","시전자의 위치에 \0311\031의 생명력을 지닌 바람의 토템을 소환하여 \0312\031 동안 30미터 반경 내에 있는 공격대원들이 마법 시전 방해 및 침묵 효과에 면역이 되게 합니다.",{0,1},{1,2}}}
rows[108280]={title={{18,789580124},"치유의 해일 토템"}}
rows[108281]={title={{18,1394929361},"고대의 인도"},description={"^when you deal direct damage or healing for the next ([%+%-]?%d[%d,.]* %a+), ([%+%-]?%d[%d,.%+%-to –]*)%% of damage or ([%+%-]?%d[%d,.%+%-to –]*)%% of healing is copied as healing to up to 3 nearby injured party or raid members%.$","다음 \0311\031 동안 직접 공격으로 입힌 피해의 \0312\031% 또는 직접 치유 주문으로 치유한 생명력의 \0313\031%를 생명력으로 복제하여, 주위 부상당한 파티원 또는 공격대원을 최대 3명까지 치유합니다.",{1,0,0},{1,2,3}},aura={{109,489033748},"입힌 피해 또는 치유한 생명력의 일정 비율을 생명력으로 복제하여 주위 부상당한 파티원 또는 공격대원을 최대 3명까지 치유"}}
rows[108282]={title={{12,559513166},"전도력"}}
rows[108283]={title={{20,1645090127},"정기의 메아리"},description={{137,238056111},"주문이 직접 피해 또는 직접 치유 효과를 일으키면, 해당 주문의 효과를 복제하는 정기의 메아리 효과를 일정 확률로 얻습니다."}}
rows[108284]={title={{19,967186726},"토템의 지속력"},description={{178,1571034838},"같은 원소의 토템을 두 개째 소환해도 첫 번째 토템이 파괴되지 않습니다.\010\010이 효과는 한 번에 한 개의 토템에만 적용됩니다. 불의 토템에는 영향을 주지 않습니다."}}
rows[108285]={title={{20,1686209554},"원소의 부름"},description={{108,1429706569},"활성화하면, 3분 미만의 기본 재사용 대기시간을 지닌 모든 토템의 재사용 대기시간이 즉시 초기화됩니다."}}
rows[108287]={title={{18,1850283569},"토템 재배치"},description={{55,883105875},"활성화된 토템을 지정된 위치로 재배치합니다."}}
rows[108288]={title={{17,1476175004},"야생의 정수"},description={"^increases stamina, agility, and intellect by ([%+%-]?%d[%d,.%+%-to –]*)%% at all times%. when activated, increases all healing done and dramatically improves the druid's ability to perform roles outside of their normal specialization for ([%+%-]?%d[%d,.]* %a+)%. grants the following benefits based on current specialization: |cffffffffnon%-guardian|r while in bear form, agility, expertise, hit chance, and armor bonuses increased, vengeance granted, chance to be hit by melee critical strikes reduced%. |cffffffffnon%-feral|r while in cat form, agility, hit chance, and expertise increased%. |cffffffffnon%-restoration|r mana cost of all healing spells reduced by 100%%%. guardian druids may also cast rejuvenation while shapeshifted%. |cffffffffnon%-balance|r spell damage and hit chance increased%. mana cost of all damage spells reduced by 100%%%.$","체력, 민첩성, 지능이 항시 \0311\031%만큼 증가합니다. 활성화되면 \0312\031 동안 모든 주문의 치유량이 증가하고 선택한 전문화 외의 역할을 수행할 능력이 대폭 상승합니다. 현재 전문화에 따라 다음과 같은 효과를 얻습니다.\010\010|CFFFFFFFF수호 외 전문화|R\010곰 변신 상태에서 민첩성, 숙련, 적중, 방어도 보너스가 증가하고, 복수심을 사용할 수 있으며, 근접 치명타에 적중당할 확률이 감소합니다.\010\010|CFFFFFFFF야성 외 전문화|R\010표범 변신 상태에서 민첩성, 적중, 숙련이 증가합니다.\010\010|CFFFFFFFF회복 외 전문화|R\010모든 치유 주문의 마나 소모량이 100%만큼 감소합니다. 수호 드루이드는 변신 중에도 회복을 시전할 수 있습니다.\010\010|CFFFFFFFF조화 외 전문화|R\010주문 피해와 적중이 증가합니다. 공격 주문의 마나 소모량이 100%만큼 감소합니다.",{0,1},{1,2}}}
rows[108291]={title={{17,1476175004},"야생의 정수"},description={"^increases stamina, agility, and intellect by ([%+%-]?%d[%d,.%+%-to –]*)%% at all times%. when activated, dramatically improves the druid's ability to perform roles outside of balance specialization for ([%+%-]?%d[%d,.]* %a+)%. grants the following benefits in the listed roles: |cffffffffguardian|r while in bear form, agility, expertise, hit chance, and armor bonuses increased, vengeance granted, and chance to be hit by melee critical strikes reduced%. |cffffffffferal|r while in cat form, agility, hit chance, and expertise increased%. |cffffffffrestoration|r healing increased and mana cost of all healing spells reduced by 100%%%.$","체력, 민첩성, 지능이 항시 \0311\031%만큼 증가합니다. 활성화되면 \0312\031 동안 조화 전문화 외의 역할을 수행할 능력이 대폭 상승합니다. 다음과 같은 역할 효과를 얻습니다.\010\010|CFFFFFFFF수호|R\010곰 변신 상태에서 민첩성, 숙련, 적중, 방어도 보너스가 증가하고, 복수심을 사용할 수 있으며, 근접 치명타에 적중당할 확률이 감소합니다.\010\010|CFFFFFFFF야성|R\010표범 변신 상태에서 민첩성, 적중, 숙련이 증가합니다.\010\010|CFFFFFFFF회복|R\010치유량이 증가하고 모든 치유 주문의 마나 소모량이 100%만큼 감소합니다.",{0,1},{1,2}},aura={{70,551541511},"표범 및 곰 변신 상태에서 치유 기술 강화"}}
rows[108292]={title={{17,1476175004},"야생의 정수"},description={"^increases stamina, agility, and intellect by ([%+%-]?%d[%d,.%+%-to –]*)%% at all times%. when activated, dramatically improves the druid's ability to perform roles outside of feral specialization for ([%+%-]?%d[%d,.]* %a+)%. grants the following benefits in the listed roles: |cffffffffguardian|r while in bear form, agility, expertise, hit chance, and armor bonuses increased, vengeance granted, and chance to be hit by melee critical strikes reduced%. |cffffffffrestoration|r healing increased and mana cost of all healing spells reduced by 100%%%. |cffffffffbalance|r spell damage and hit chance increased%. mana cost of all damage spells reduced by 100%%%.$","체력, 민첩성, 지능이 항시 \0311\031%만큼 증가합니다. 활성화되면 \0312\031 동안 야성 전문화 외의 역할을 수행할 능력이 대폭 상승합니다. 현재 전문화에 따라 다음과 같은 효과를 얻습니다.\010\010|CFFFFFFFF수호|R\010곰 변신 상태에서 민첩성, 숙련, 적중, 방어도 보너스가 증가하고, 복수심을 사용할 수 있으며, 근접 치명타에 적중당할 확률이 감소합니다.\010\010|CFFFFFFFF회복|R\010치유량이 증가하고 모든 치유 주문의 마나 소모량이 100%만큼 감소합니다. 수호 드루이드는 변신 중에도 회복을 시전할 수 있습니다.\010\010|CFFFFFFFF조화|R\010주문 피해와 적중이 증가합니다. 공격 주문의 마나 소모량이 100%만큼 감소합니다.",{0,1},{1,2}},aura={{74,1944403810},"곰 변신 시 치유 및 공격 주문 능력 강화"}}
rows[108293]={title={{17,1476175004},"야생의 정수"},description={"^increases stamina, agility, and intellect by ([%+%-]?%d[%d,.%+%-to –]*)%% at all times%. when activated, dramatically improves the druid's ability to perform roles outside of guardian specialization for ([%+%-]?%d[%d,.]* %a+)%. grants the following benefits in the listed roles: |cffffffffferal|r while in cat form, agility, hit chance, and expertise increased%. |cffffffffrestoration|r healing increased and mana cost of all healing spells reduced by 100%%%. allows rejuvenation to be cast while shapeshifted%. |cffffffffbalance|r spell damage and hit chance increased%. mana cost of all damage spells reduced by 100%%%.$","체력, 민첩성, 지능이 항시 \0311\031%만큼 증가합니다. 활성화되면 \0312\031 동안 수호 전문화 외의 역할을 수행할 능력이 대폭 상승합니다. 다음과 같은 역할 효과를 얻습니다.\010\010|CFFFFFFFF야성|R\010표범 변신 상태에서 민첩성, 적중, 숙련이 증가합니다.\010\010|CFFFFFFFF회복|R\010치유량이 증가하고 모든 치유 주문의 마나 소모량이 100%만큼 감소합니다. 변신 중에 회복을 시전할 수 있습니다.\010\010|CFFFFFFFF조화|R\010주문 피해와 적중이 증가합니다. 공격 주문의 마나 소모량이 100%만큼 감소합니다.",{0,1},{1,2}},aura={{75,1840341739},"표범 변신 상태에서 치유 및 공격 주문 강화"}}
rows[108294]={title={{17,1476175004},"야생의 정수"},description={"^increases stamina, agility, and intellect by ([%+%-]?%d[%d,.%+%-to –]*)%% at all times%. when activated, increases all healing done by ([%+%-]?%d[%d,.%+%-to –]*)%% and dramatically improves the druid's ability to perform roles outside of restoration specialization for ([%+%-]?%d[%d,.]* %a+)%. grants the following benefits in the listed roles: |cffffffffguardian|r while in bear form, agility, expertise, hit chance, and armor bonuses increased, vengeance granted, and chance to be hit by melee critical strikes reduced%. |cffffffffferal|r while in cat form, agility, hit chance, and expertise increased%. |cffffffffbalance|r spell damage and hit chance increased%. mana cost of all damage spells reduced by 100%%%.$","체력, 민첩성, 지능이 항시 \0311\031%만큼 증가합니다. 활성화되면 \0313\031 동안 모든 치유량이 \0312\031%만큼 증가하고 회복 전문화 외의 역할을 수행할 능력이 대폭 상승합니다. 다음과 같은 역할 효과를 얻습니다.\010\010|CFFFFFFFF수호|R\010곰 변신 상태에서 민첩성, 숙련, 적중, 방어도 보너스가 증가하고, 복수심을 사용할 수 있으며, 근접 치명타에 적중당할 확률이 감소합니다.\010\010|CFFFFFFFF야성|R\010표범 변신 상태에서 민첩성, 적중, 숙련이 증가합니다.\010\010|CFFFFFFFF조화|R\010주문 피해와 적중이 증가합니다. 공격 주문의 마나 소모량이 100%만큼 감소합니다.",{0,0,1},{1,2,3}},aura={{75,186139808},"공격 주문 강화 및 표범 변신과 곰 변신 상태에서의 효율성 증가"}}
