rows[109197]={title={{13,2076775095},"촉수 던지기"},description={"^grabs a nearby enemy and throws them at another target dealing ([%+%-]?%d[%d,.%+%-to –]*) physical damage to all targets within 7 yards%.$","근처에 있는 대상을 붙잡아 다른 대상에게 던집니다. 7미터 안에 있는 모든 적에게 \0311\031의 물리 피해를 입힙니다.",{0},{1}},aura={"^grabs a nearby enemy and throws them at another target dealing ([%+%-]?%d[%d,.%+%-to –]*) physical damage to all targets within 7 yards%.$","근처에 있는 대상을 붙잡아 다른 대상에게 던집니다. 7미터 안에 있는 모든 적에게 \0311\031의 물리 피해를 입힙니다.",{0},{1}}}
