rows[109199]={title={{10,1215499411},"마구 패기"},description={"^inflict ([%+%-]?%d[%d,.%+%-to –]*) physical damage to all enemies within 15 yards and knocks them away%.$","반경 15미터 안에 있는 모든 적에게 \0311\031의 물리 피해를 입히고 뒤로 밀쳐냅니다.",{0},{1}},aura={"^inflict ([%+%-]?%d[%d,.%+%-to –]*) physical damage toall enemies within 15 yards and knocks them away%.$","반경 15미터 안에 있는 모든 적에게 \0311\031의 물리 피해를 입히고 뒤로 밀쳐냄",{0},{1}}}
rows[109200]={title={{12,1415560377},"사그라지는 빛"},description={"^sucks the light out of the target, drawing them into twilight%. upon expiration, targets in the twilight realm will be instantly killed%. targets in the normal realm will be pulled into the twilight realm, and all threat against ultraxion will be reset%. additionally, no threat will be generated for ([%+%-]?%d[%d,.]* %a+)%.$","대상으로부터 빛의 힘을 빨아들여, 황혼 속으로 끌어들입니다. 효과가 사라질 때, 대상이 황혼 세계에 있으면 즉사합니다. 대상이 현실 세계에 있으면 황혼 세계로 끌려들어가며, 울트락시온에 대한 위협 수준이 초기화됩니다. 추가로 \0311\031 동안은 위협 수준이 생성되지 않습니다.",{1},{1}}}
