rows[109259]={title={{9,1731166148},"강화 사격"},description={"^you wind up a powerful shot, which deals ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage to the target and ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage to all enemies in between you and the target%. enemies hit by powershot are also knocked back%.$","강력한 사격으로 대상에게 무기 공격력의 \0311\031%에 해당하는 피해를 입히고 자신과 대상 사이에 있는 모든 적에게 무기 공격력의 \0312\031%에 해당하는 피해를 입힙니다.\010\010또한, 적중시킨 적을 뒤로 밀쳐냅니다.",{0,0},{1,2}}}
