rows[110316]={title={{16,1623917807},"서릿발 덫"},description={"^place a frost trap that creates an ice slick around itself for ([%+%-]?%d[%d,.]* %a+) when the first enemy approaches it%. all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards will be slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% while in the area of effect%. trap will exist for ([%+%-]?%d[%d,.]* %a+)%.$","서릿발 덫을 설치합니다. 적이 다가오면 덫에서 가느다란 얼음실이 퍼져 나와, \0311\031 동안 \0312\031미터 반경 이내 적의 이동 속도를 \0313\031%만큼 감소시킵니다. 덫은 \0314\031 동안 지속됩니다.",{1,0,0,1},{1,2,3,4}},aura={"^movement speed slowed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","이동 속도 \0311\031%만큼 감소",{0},{1}}}
rows[110317]={title={{19,1659757031},"물의 참호"},description={"^drowning within hagara's water bubble causes ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health to be lost and reduces movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","하가라의 물거품에 삼켜지면 최대 생명력의 \0311\031%에 해당하는 피해를 입고 이동 속도가 \0312\031%만큼 감소합니다.",{0,0},{1,2}},aura={"^unable to breathe%. ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health as frost damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","호흡 불가\010\0312\031초마다 최대 생명력의 \0311\031%에 해당하는 냉기 피해\010이동 속도 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
