rows[110570]={title={{16,1226943811},"대마법 보호막"},description={"^surrounds the druid in an anti%-magic shell, absorbing ([%+%-]?%d[%d,.%+%-to –]*)%% of the damage dealt by harmful spells %(up to a maximum of ([%+%-]?%d[%d,.%+%-to –]*)%% of the druid's health%) and preventing application of harmful magical effects%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","자신을 대마법 보호막으로 감싸 해로운 주문으로 받는 피해를 \0311\031%만큼(전체 생명력의 \0312\031%까지) 흡수하고 해로운 마법 효과에 걸리지 않게 합니다. \0313\031 동안 지속됩니다.",{0,0,1},{1,2,3}},aura={"^spell damage reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. immune to magic debuffs%.$","주문 피해 \0311\031%만큼 감소\010마법 약화 효과에 면역",{0},{1}}}
