rows[110588]={title={{12,1067181272},"눈속임"},description={"^the current party or raid member targeted will receive the threat caused by your next damaging attack and all actions taken for ([%+%-]?%d[%d,.]* %a+) afterwards%. transferred threat is not permanent, and will fade after 30 sec%.$","다음 공격과 그 후 \0311\031 동안 위협 수준을 발생시키는 자신의 모든 행동을 대상 파티원 또는 공격대원이 행한 것으로 속입니다. 이전된 위협은 30초 동안만 유지됩니다.",{1},{1}},aura={{19,853656592},"위협 수준 대상 변경"}}
rows[110591]={title={{12,1067181272},"눈속임"},description={"^threat caused for the next ([%+%-]?%d[%d,.]* %a+) is redirected to the target raid member%.$","다음 \0311\031 동안 발생되는 위협 수준을 대상 공격대원이 가한 것으로 속입니다.",{1},{1}},aura={{39,1640020302},"드루이드의 공격으로 위협 수준 생성"}}
rows[110597]={title={{9,2122586079},"죽은 체하기"},description={"^play dead, tricking enemies into ignoring you%. lasts up to ([%+%-]?%d[%d,.]* %a+)%.$","적을 속여 자신이 죽은 것처럼 보이게 만듭니다. 최대 \0311\031 동안 지속됩니다.",{1},{1}},aura={{13,288428111},"죽은 시늉"}}
rows[110600]={title={{8,1481725278},"얼음의 덫"},description={"^place a frost trap that creates an ice slick around itself for ([%+%-]?%d[%d,.]* %a+) when the first enemy approaches it%. all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards will be slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% while in the area of effect%. trap will exist for ([%+%-]?%d[%d,.]* %a+)%.$","얼음의 덫을 설치합니다. 적이 다가오면 덫에서 가느다란 얼음실이 퍼져 나와, \0311\031 동안 \0312\031미터 반경 이내 적의 이동 속도를 \0313\031%만큼 감소시킵니다. 덫은 \0314\031 동안 지속됩니다.",{1,0,0,1},{1,2,3,4}}}
