rows[110617]={title={{10,203040579},"공격 저지"},description={"^when activated, increases the chance melee attacks will miss you by ([%+%-]?%d[%d,.%+%-to –]*)%%, reduces the chance ranged attacks will hit you by ([%+%-]?%d[%d,.%+%-to –]*)%% and grants a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to deflect spells%. while deterrence is active, you cannot attack%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","활성화되면 근접 공격에 적중당하지 않을 확률이 \0311\031%만큼 증가하고 원거리 공격에 적중당하지 않을 확률이 \0311\031%만큼 증가하며, \0313\031%의 확률로 주문을 튕겨냅니다. 이 동안에는 공격할 수 없습니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,1,3,4}},aura={"^chance to be missed by melee attacks increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, chance for ranged attacks to miss you increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, ([%+%-]?%d[%d,.%+%-to –]*)%% chance to deflect spells, and unable to attack%.$","근접 공격에 적중당하지 않을 확률 \0311\031%만큼 증가\010원거리 공격에 적중당하지 않을 확률 \0312\031%만큼 증가\010\0312\031%의 확률로 주문 튕겨냄\010공격 불가",{0,0,0},{1,2,2}}}
rows[110618]={title={{10,203040579},"공격 저지"},description={"^when activated, increases parry chance by ([%+%-]?%d[%d,.%+%-to –]*)%%, reduces the chance ranged attacks will hit you by ([%+%-]?%d[%d,.%+%-to –]*)%% and grants a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to deflect spells%. while deterrence is active, you cannot attack%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","활성화되면 무기 막기 확률이 \0311\031%만큼 증가하고 원거리 공격에 적중당하지 않을 확률이 \0311\031%만큼 증가하며, \0313\031%의 확률로 주문을 튕겨냅니다. 이 동안에는 공격할 수 없습니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,1,3,4}},aura={"^parry chance increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, chance for ranged attacks to miss you increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, ([%+%-]?%d[%d,.%+%-to –]*)%% chance to deflect spells, and unable to attack%.$","무기 막기 확률 \0311\031%만큼 증가\010원거리 공격에 적중당하지 않을 확률 \0312\031%만큼 증가\010\0312\031%의 확률로 주문 튕겨냄\010공격 불가",{0,0,0},{1,2,2}}}
