rows[110693]={title={{10,1966086066},"얼음 회오리"},description={"^blasts enemies near the caster, freezing them in place for up to ([%+%-]?%d[%d,.]* %a+)%. damage caused may interrupt the effect%.$","주위 적을 냉기로 강타하여 최대 \0311\031 동안 그 자리에 얼어붙게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.",{1},{1}},aura={{16,147316927},"얼어붙음"}}
