rows[110695]={title={{9,1679727355},"빙결 화살"},description={"^launches a frost trap that freezes the first enemy that approaches, preventing all action for up to ([%+%-]?%d[%d,.]* %a+)%. any damage caused will break the ice%. trap will exist for ([%+%-]?%d[%d,.]* %a+)%. only one trap can be active at a time%.$","냉기의 덫을 설치합니다. 적이 다가오면 얼려서 최대 \0311\031 동안 모든 행동을 불가능하게 만듭니다. 덫에 걸린 적이 피해를 입으면 효과가 풀립니다. 덫은 \0312\031 동안 지속되며, 한 개만 놓아둘 수 있습니다.",{1,1},{1,2}}}
rows[110696]={title={{9,1960685663},"얼음 방패"},description={"^you become encased in a block of ice, protecting you from all physical attacks and spells for ([%+%-]?%d[%d,.]* %a+), but during that time you cannot attack, move or cast spells%.$","커다란 얼음 덩어리에 둘러싸여 \0311\031 동안 모든 물리 공격과 주문으로부터 보호받습니다. 하지만 이 동안은 공격하거나 이동하거나 마법을 사용하지 못합니다.",{1},{1}},aura={{68,56642901},"모든 공격 및 주문에 면역\010공격, 이동, 주문 사용 불가"}}
