rows[110747]={title={{22,470136628},"슈마의 암청색 피"},description={{142,540865667},"능력 부여: 마나 공허\010마나 공허는 대상이 죽을 때까지 계속해서 마나를 흡수하는 능력입니다. 시전자가 죽으면 대상은 빼앗긴 마나를 모두 회복합니다."},aura={{142,540865667},"능력 부여: 마나 공허\010마나 공허는 대상이 죽을 때까지 계속해서 마나를 흡수하는 능력입니다. 시전자가 죽으면 대상은 빼앗긴 마나를 모두 회복합니다."}}
