rows[110803]={title={{16,1093971294},"번개 보호막"},description={"^the caster is surrounded by a reactive lightning barrier%. when a spell, melee or ranged attack hits the caster, the attacker will be struck for ([%+%-]?%d[%d,.%+%-to –]*) nature damage%. this effect may only occur once every few seconds%. lasts ([%+%-]?%d[%d,.]* %a+)%. only one of your elemental shields can be active on a target at once%.$","적의 공격에 반응하는 번개 보호막이 시전자 주위에 머무릅니다. 시전자가 주문 공격이나 근접 또는 원거리 공격에 적중당하면 공격자에게 \0311\031의 자연 피해를 입힙니다. 이 때 구슬이 하나씩 사라집니다. 이 효과는 몇 초마다 한 번씩만 발동합니다. \0312\031 동안 지속됩니다.\010\010원소 보호막은 한 대상에게 동시에 하나만 유지할 수 있습니다.",{0,1},{1,2}},aura={{33,932289852},"공격자에게 자연 피해"}}
