rows[110806]={title={{20,399630876},"영혼나그네의 은총"},description={"^calls upon spiritual guidance, permitting movement while casting non%-instant druid spells%. this spell may be cast while casting other spells%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","영혼의 인도로 이동 중에도 시전 시간이 있는 주문을 시전할 수 있습니다. 이 주문은 다른 주문을 시전하는 도중 시전할 수 있습니다. \0311\031 동안 지속됩니다.",{1},{1}},aura={{62,1654776305},"이동 중에도 시전 시간이 있는 주문 시전 가능"}}
