rows[112932]={title={{14,1910939944},"악의의 고리"},description={"^encircles the caster in a ring of shadows that inflicts ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. to enemies it touches%. while active, the caster's movement is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","암흑의 고리로 몸을 감싸, 닿는 적에게 \0312\031초마다 \0311\031의 피해를 입힙니다. 이 동안 시전자의 이동 속도는 \0313\031%만큼 감소합니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}},aura={"^encircled by a ring of shadows that inflicts ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. to enemies it touches%. movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","닿는 적에게 \0312\031초마다 \0311\031의 피해\010이동 속도 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
rows[112933]={title={{14,1910939944},"악의의 고리"},description={"^encircles the caster in a ring of shadows that inflicts ([%+%-]?%d[%d,.%+%-to –]*) damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. to enemies it touches%. while active, the caster's movement is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","암흑의 고리로 몸을 감싸, 닿는 적에게 \0312\031초마다 \0311\031의 피해를 입힙니다. 이 동안 시전자의 이동 속도는 \0313\031%만큼 감소합니다. \0314\031 동안 지속됩니다.",{0,0,0,1},{1,2,3,4}}}
