rows[112947]={title={{12,1368446348},"신경쇠약"},description={"^a successful kidney shot or cheap shot also reduces the damage dealt by the target by ([%+%-]?%d[%d,.%+%-to –]*)%% %(25%% on player targets%) and healing done by the target by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+) after the effect fades%.$","급소 가격 또는 비열한 습격을 적중시키면, 효과가 사라진 다음 \0313\031 동안 대상의 공격력이 \0311\031%(대상이 플레이어면 25%)만큼, 치유량이 \0312\031%만큼 감소합니다.",{0,0,1},{1,2,3}},aura={"^damage dealt reduced by ([%+%-]?%d[%d,.%+%-to –]*)%% and healing done reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격력 \0311\031%만큼 감소\010치유량 \0312\031%만큼 감소",{0,0},{1,2}}}
rows[112948]={title={{10,1939107796},"서리 폭탄"},description={"^places a frost bomb on the target%. after ([%+%-]?%d[%d,.]* %a+), the bomb explodes, dealing ([%+%-]?%d[%d,.%+%-to –]*) frost damage to the primary target, and ([%+%-]?%d[%d,.%+%-to –]*) frost damage to all other targets within ([%+%-]?%d[%d,.%+%-to –]*) yds%. all affected targets are slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. frost bomb's countdown and cooldown are reduced by haste%. this spell is strongest when it can hit 5 or more targets with the explosion%.$","대상에게 서리 폭탄을 안겨 \0311\031 후 폭발하게 합니다. 주 대상에게 \0312\031의 냉기 피해를 입히고 \0314\031미터 반경 내에 있는 다른 모든 대상에게 \0313\031의 냉기 피해를 입힙니다. 서리 폭탄의 영향을 받은 대상은 \0316\031 동안 이동 속도가 \0315\031%만큼 감소합니다. 서리 폭탄의 초읽기 시간과 재사용 대기시간은 가속의 영향을 받아 감소할 수 있습니다. 다섯 또는 그 이상의 대상에게 폭발했을 때 가장 강력한 위력을 발휘합니다.",{1,0,0,0,0,1},{1,2,3,4,5,6}},aura={"^after ([%+%-]?%d[%d,.]* %a+), the bomb explodes, dealing ([%+%-]?%d[%d,.%+%-to –]*) frost damage to the primary target, and ([%+%-]?%d[%d,.%+%-to –]*) frost damage to all other targets within ([%+%-]?%d[%d,.%+%-to –]*) yds%. all affected targets are slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0311\031 후 폭발하여 주 대상에게 \0312\031의 냉기 피해 및 \0314\031미터 반경 내 다른 모든 대상에게 \0313\031의 냉기 피해\010서리 폭탄의 영향을 받은 대상은 \0316\031 동안 이동 속도 \0315\031%만큼 감소",{1,0,0,0,0,1},{1,2,3,4,5,6}}}
