rows[112961]={title={{15,1418931662},"착취 독"},description={"^poisons an enemy for ([%+%-]?%d[%d,.]* %a+)%. subsequent weapon strikes against the poisoned target will heal the rogue for ([%+%-]?%d[%d,.%+%-to –]*)%% of damage dealt%.$","\0311\031 동안 적을 중독시킵니다. 이후 중독된 대상에게 무기 공격을 가하면 입힌 피해의 \0312\031%만큼 도적이 생명력을 회복합니다.",{1,0},{1,2}},aura={"^melee attacks suffered from the poisoning rogue will heal the rogue for ([%+%-]?%d[%d,.%+%-to –]*)%% of damage received%.$","중독시킨 도적으로부터 근접 공격을 받으면, 받은 피해의 \0311\031%만큼 도적이 생명력 회복",{0},{1}}}
