rows[112974]={title={{15,1418931662},"착취 독"},description={"^poisons an enemy for ([%+%-]?%d[%d,.]* %a+)%. subsequent weapon strikes against the poisoned target will heal the rogue for ([%+%-]?%d[%d,.%+%-to –]*)%% of damage dealt%.$","\0311\031 동안 적을 중독시킵니다. 이후 중독된 대상에게 무기 공격을 가하면 입힌 피해의 \0312\031%만큼 도적이 생명력을 회복합니다.",{1,0},{1,2}}}
