rows[112997]={title={{15,902820152},"분쇄의 일격"},description={"^deliver an armor%-shattering blow to your enemy, causing ([%+%-]?%d[%d,.%+%-to –]*) damage, reducing armor on the target by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+) or removing any invulnerabilities%. using this ability activates cat form%.$","적의 방어구를 분쇄하는 일격을 가해 \0311\031의 피해를 입히고 \0313\031 동안 대상의 방어도를 \0312\031%만큼 감소시키거나 무적 효과를 제거합니다. 이 기술을 사용하면 표범으로 변신합니다.",{0,0,1},{1,2,3}},aura={"^armor reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","방어도 \0311\031%만큼 감소",{0},{1}}}
