rows[112999]={title={{14,1717357294},"고통의 저주"},description={"^curses an enemy with agony, inflicting shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. over ([%+%-]?%d[%d,.]* %a+)%. only one curse per warlock can be active on any one target%.$","적에게 고통의 저주를 걸어 \0312\031에 걸쳐 \0311\031초마다 암흑 피해를 입힙니다. 한 대상에 동시에 하나의 저주만 걸 수 있습니다.",{0,1},{1,2}},aura={"^shadow damage inflicted every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0311\031초마다 암흑 피해",{0},{1}}}
