rows[113043]={title={{15,1563540358},"청명의 전조"},description={"^your periodic healing from lifebloom has a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to cause you to enter a clearcasting state%. the clearcasting state reduces the mana, rage or energy cost of your next cast%-time damaging or healing spell or offensive feral ability by ([%+%-]?%d[%d,.%+%-to –]*)%%%. does not affect nourish%.$","피어나는 생명으로 주기적인 치유를 할 때마다 \0311\031% 확률로 번뜩임 상태를 취합니다.\010\010번뜩임 상태에서는 시전 시간이 있는 다음 공격, 치유 주문이나 야성 공격 기술의 마나, 분노, 기력 소비량이 \0312\031%만큼 감소합니다. 육성 주문에는 영향을 주지 않습니다.",{0,0},{1,2}},aura={{99,1381132121},"피어나는 생명으로 주기적인 치유를 할 때마다 일정 확률로 번뜩임 상태를 취함"}}
