rows[113968]={title={{16,558812730},"판다렌 다기 세트"},description={{404,707304347},"판다렌이 좋아하는 차는 다채로운 역사를 자랑합니다. 판다렌은 차를 끓일 때 들이는 정성만큼이나 차를 즐기는 비법도 중요하게 여깁니다. 이 소박한 다기는 모구 통치 시절에 만들어진 것으로, 고통과 폭압의 세월을 살아낸 주인에게 위로와 휴식을 안겨 주던 물건들이었습니다. 금이 가고 부서졌지만 소박한 삶의 즐거움에서 위안을 찾는 모습을 보여주는 다기입니다."}}
rows[113969]={title={{9,1597450294},"무방비"},description={"^damage taken increased by ([%+%-]?%d[%d,.%+%-to –]*)%%$","받는 피해가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^damage taken increased by ([%+%-]?%d[%d,.%+%-to –]*)%%$","받는 피해 \0311\031%만큼 증가",{0},{1}}}
rows[113970]={title={{9,1597450294},"무방비"},description={"^damage taken increased by ([%+%-]?%d[%d,.%+%-to –]*)%%$","받는 피해가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^damage taken increased by ([%+%-]?%d[%d,.%+%-to –]*)%%$","받는 피해 \0311\031%만큼 증가",{0},{1}}}
rows[113971]={title={{19,455660105},"판다렌 놀이판"},description={{171,278246610},"판다렌은 놀이를 좋아합니다. 특히 장기는 판다렌의 초대 황제가 통치하던 무렵부터 판다렌이 가장 좋아했던 놀이입니다. 이 고대의 장기판과 장기 말은 아주 훌륭하게 잘 보존되었습니다."}}
rows[113972]={title={{41,1667299412},"양조대부 취앤 토우 쿠오의 쌍둥이 잔"},description={{603,1699564730},"흑단과 옥으로 만든 맥주잔 한 벌입니다. 양조대부 \"두 주먹\" 취앤 토우 쿠오는 두 종류의 주류를 완벽하게 섞어 독주의 부작용을 완화하려 했습니다. 영혼의 에일 맥주와 정신의 흑맥주를 적정한 비율로 같이 마시면, 위장 속에서 섞이면서 덜 정제된 주류를 마셨을 때 흔히 경험하는 판단력과 자기절제의 상실 없이 깨달음과 친선의 상태에 이르게 됩니다. 불행히도 양조대부의 이 비밀은 세월이 흐르면서 사라졌지만, 아름답게 조각된 이 맥주잔은 그의 숙련된 기술을 영원히 간직하고 있습니다."}}
rows[113973]={title={{34,351926336},"양조대부 런 윈의 보행 지팡이"},description={{647,30237510},"고래뼈를 깎아 만든 손잡이를 얹은 이 기다란 지팡이는 수수께끼에 싸여 있는 인물 런 윈이 사용하던 것입니다. 런윈은 태어날 때부터 장님이었기에 다른 감각이 비상하게 발달했고, 당대의 음용주가 하나같이 맛이 거칠거나 쓰다는 것을 깨달았습니다. 그는 몇 년 동안이나 실험을 거듭한 끝에 자신의 나머지 네 가지 감각에 완벽하게 들어맞는 네 가지 완벽한 맛을 개발했지만, 동시에 네 가지 감각에 모두 들어맞는 \"하나의 맛\"을 개발하지는 못했습니다. 그는 장수를 누리다가 죽을 때가 되어서야 궁극의 비법, \"네 감각의 맥주\"를 완성시켰고, 이는 당대의 가장 훌륭한 발명품이 되었습니다. 슬프게도 그 비법은 세월이 흐르면서 잊혔는데, 런 윈의 필적이 워낙 알아보기가 어려웠기 때문이었습니다."}}
rows[113974]={title={{34,980958804},"양조대부 신 워 인의 빈 맥주통"},description={{532,215962968},"심장 모양의 수도꼭지가 붙어 있어 지금은 사망한 저 양조대부, 일명 \"부서진 마음\" 신 워 인의 유물임을 알 수 있는 통입니다. 몇 세대 전 인물인 양조대부 신 워 인은 술을 마시는 이의 몸을 한없는 따스함과 행복감으로 가득 채워주는 혼합주인 \"기쁨가득 맥주\"를 만들어냈습니다. 신 워 인은 자신이 만든 술을 너무나 사랑한 나머지 자신의 양조장에서 술통이 팔려나갈 때마다 비탄에 잠겨 목놓아 울었다고 합니다. 이 통에도 그의 눈물이 스며 있을지 모릅니다. 술통이 비어 있으니 조금 실망스럽기도 합니다."}}
rows[113975]={title={{20,643060020},"조각된 청동 거울"},description={{259,1474898993},"앞면은 오래전에 없어졌지만 뒷면은 정교한 조각이 새겨진 청동 원형 거울입니다. 뒷면의 조각은 희망의 주학을 묘사했으며, \"사랑하는 린에게 / 나의 아름다움, 나의 비둘기여 / 이 완벽한 그림이야말로 / 그대 모습이리 / 내 사랑 - 야오\"라는 글귀가 새겨져 있습니다."}}
rows[113976]={title={{39,342023266},"금으로 세공된 장례의식용 도자기 조각상"},description={{352,919389117},"사랑하는 이의 죽음을 애도하여 의뢰하는 이런 조각상은 상실감을 극복하는 데 도움이 됩니다. 이 조각상은 린이라는 이름의 젊고 아름다운 판다렌 전승지기를 본떠서 만들어졌습니다. 새겨진 글을 보면 그녀는 호젠 황제 리크틱의 짧은 통치 기간 중 네 바람의 계곡을 휩쓴 무시무시한 열병에 걸려 사망했습니다."}}
rows[113977]={title={{15,1440484375},"연금술 그릇"},description={{471,1405062586},"온전한 청동 연금술사 단지 한 벌입니다. 깔끔하게 새겨진 꼬리표는 단지 안에 강력한 치유 약초가 복잡한 배열로 보존되어 있음을 나타내고 있습니다. 이 약초 대부분은 이제 정확한 쓰임새를 알 수 없지만, 단지를 담은 상자의 명판에 적힌 '의술사 야오 펌포우'는 그 놀라운 능력 덕분에 지금도 네 바람의 계곡에서 건강과 안녕의 상징이 되어 있습니다. 야오는 평생 독신이었는데, 전설에 따르면 실연 때문이었다고 합니다."}}
rows[113978]={title={{15,1635948247},"위론의 진주"},description={{427,1260832762},"옥으로 만든 보주 한가운데에 자기 꼬리를 물고 있는 용이 새겨져 있습니다. 위쪽과 아래쪽에는 각각 \"확실한 것은 오직 하나뿐이니, 모든 끝은 새로운 시작을 의미한다.\"라는 글이 새겨져 있습니다. 이 보주는 판다렌의 황제 슈 블라인드아이 시대에 옥룡을 기리기 위해 만들어진 것으로, 100년마다 새로운 몸을 얻어 태어나는 옥룡을 상징합니다. 위론은 지금도 비취 숲에 있는 사원에서 지혜와 통찰을 내려주고 있습니다."}}
rows[113979]={title={{18,916223339},"니우짜오의 깃발"},description={{342,2094404430},"두꺼운 천 두루마리를 높이 들자, 밑으로 펼쳐지면서 판다렌 제국의 자랑스러운 문장이 드러납니다. 묵직한 강철 고리가 매달린 긴 가죽 띠가 깃발을 아래에서 팽팽하게 당겨줍니다. 가죽 띠마다 기수의 용기를 북돋우는 글귀가 자수로 새겨져 있습니다. \"두려워하면 나약해질 뿐이다. 두려움을 극복해 자신의 진면모를 드러내라.\""}}
rows[113980]={title={{18,1747174488},"츠지의 우산"},description={{592,1285909961},"기다란 대나무에 얇은 종이를 솜씨 좋게 붙여 만든 우산입니다. 기나긴 썬더포우 왕조의 어느 시대엔가 만들어졌을 이 우산은 놀라울 정도로 보존 상태가 좋습니다. 밑면에는 새까만 먹구름이 그려져 있고, 눈부시게 붉은 태양이 윗면을 장식하고 있습니다. 구름에는 우아한 붓글씨로 짤막한 문구가 적혀 있습니다. \"폭풍우가 몰아치는 먹구름 뒤에는 희망이라는 태양이 숨어 있다. 이처럼 마음에도 희망이 숨어 있지만 눈에는 보이지 않는다.\" 주학 츠지는 수 세기 동안 판다렌에게 희망의 상징이었습니다. 화려하고 아름다운 그의 사원은 네 바람의 계곡 남쪽에 있는 사악한 밀림을 내려다보고 있습니다."}}
rows[113981]={title={{13,1014409943},"쉬엔의 창"},description={{629,651353627},"잔달라 트롤 전쟁 당시 만들어진 이 강건한 창은, 놀랍도록 가벼우면서도 유연성이 뛰어납니다. 나무로 만들고 옻칠을 한 자루에는 여기저기 깊은 흠이 나 있지만, 창끝은 나무랄 데 없이 완벽해 보입니다. 창의 길이와 만들어진 시대로 판단하건대 비룡의 등에 타고 휘두르기 위한 무기일 것입니다. 닳아빠진 손잡이에는 \"유일한 적은 너 자신이다.\"라는 글귀가 새겨져 있습니다. '백호' 쉬엔은 전장에서 용맹함과 뛰어난 실력으로 이름을 떨쳤던 전설적인 존재입니다. 쿤라이 봉우리의 높은 사원에 자리한 그의 사원에서는 희망에 찬 전사들이 수련 중입니다."}}
rows[113982]={title={{21,1571852753},"반란의 수갑"},description={{239,1517354938},"강철로 주조하고 복종과 고통의 주문이 깃든 수갑입니다. 안쪽에 가시가 나 있으며,모구의 노예에게 채웠던 것입니다. 주문은 오래전에 사라졌지만 모구의 잔혹함은 지금도 보는 이의 등골을 서늘하게 합니다."}}
rows[113983]={title={{22,949843187},"금이 간 모구 마법석"},description={{510,1495780446},"마법 기술을 배워야 하는 \"열등한 종족\"과는 달리, 모구의 마법은 타고난 것입니다. 모구의 마법 사용법에 대해 알려진 바로는, 모구 마법을 마법사나 흑마법사 같은 기존 범주로 분류할 수 없었다고 합니다. 특히 주목할 점은 육체 형성이나 영혼 갈무리 마법입니다. 아제로스의 현대 종족들은 이 돌에 깃들었던 낯선 마법의 잔존물을 이해하기 어려울 것입니다. 흥미롭게도 룬 주위의 표식 중 일부는 티탄의 언어와 닮았습니다."}}
rows[113984]={title={{14,1788545841},"토우 팔"},description={{407,1322593279},"다른 모든 종족을 노예로 삼아 모조리 투사로 만들어버린 모구는, 그 대신 조형체에 생명을 불어넣는 방법을 연구하여 자신들 대신 싸우게 했습니다. 토우 전사들은 때로는 수백 년 동안이나 휴면 상태가 되기 때문에 이 토우 전사가 언제 만들어졌고 언제 사용되었는지를 잘 짐작하기는 힘듭니다. 하지만 잘린 팔의 밑동을 살펴보니 전장에서 잘려나간 것임을 알 수 있습니다."}}
rows[113985]={title={{19,1763617546},"석화된 뼈 채찍"},description={{141,1878018494},"커다란 고대 생물체의 등뼈로 만들어진 채찍입니다. 이 고통의 도구로 인해 수많은 모구 노예들이 피를 흘렸습니다."}}
rows[113986]={title={{21,2003414899},"천둥왕 휘장"},description={{150,1059295040},"서로 교차하는 번갯불과 왕관의 상징이 옥으로 만들어진 문양을 장식하고 있습니다. 모구의 제1대 황제인 레이 션 휘하의 병사들이 착용한 휘장입니다."}}
rows[113987]={title={{26,1819219548},"천둥왕의 칙령"},description={{239,1888528069},"이 칙령은 초대 제국의 통합 언어로 적혀져 있으며 돌 서판에 끌로 정교하게 새겨져 있습니다. 가장 위에 적힌 법은 선동, 폭동, 반란은 공공장소에서 적출형에 처한다는 내용입니다."}}
rows[113988]={title={{11,1954845060},"강철 아뮬렛"},description={{133,991687097},"이 거대한 강철 아뮬렛은 전투 도끼만큼이나 무겁습니다. 모구 전사들은 힘을 과시하기 위해 이런 \"공예품\"을 달고 다녔습니다."}}
rows[113989]={title={{23,989679668},"장군의 낙인"},description={{120,438810437},"하급 모구 장군의 상징을 새긴 철제 낙인으로, 가축이 아닌 노예들에게 사용된 것입니다."}}
rows[113990]={title={{9,1616241933},"모구 동전"},description={{350,1347263788},"이 화폐는 모구 황제 와이의 통치 기간에 사용되었습니다. 동전 앞면은 황제 와이를 한껏 영광스러운 모습으로 묘사해 놓았고 뒷면은 모구 왕조의 변천 과정을 보여주고 있는데, 정권을 전복시키고 말살해야만 옥좌에 오를 수 있었던 피비린내 나는 역사입니다. 여러 가지 면에서 모구 정부는 잔혹한 힘과 끔찍한 술책을 토대로 하는 실력주의 정치체제였습니다."}}
rows[113991]={title={{20,1311350469},"낡은 기념물 장부"},description={{205,1331743904},"모구는 강력한 마법을 마음대로 쓸 수 있었지만, 거대한 기념물을 지을 때는 노예 동원을 선호했습니다. 이 장부에는 거대한 기념물 하나를 짓는 동안 들인 비용과 노예의 수가 상세히 적혀 있습니다."}}
rows[113992]={title={{16,2142936544},"기렌 조각상"},description={{248,303462467},"이 조각상은 모구 황제 캉의 짧은 통치 시절 조각된 것으로 작은 돌 안에 기렌 하수인을 속박하려는 실험의 일환이었습니다. 그러나 속박된 기렌은 힘을 잃어 쓸모없게 되어버렸기에, 이 실험은 폐지되었습니다."}}
rows[113993]={title={{16,154810504},"인체 표본"},description={{78,1693264495},"판다렌 인체 표본입니다. 고문 기술을 기록할 때 사용했습니다."}}
rows[113995]={title={{9,1022938902},"클릭하세요!"}}
rows[113996]={title={{10,2062482925},"뼈 갑옷"},description={{73,2092867463},"시전자를 뼈 갑옷으로 감싸 뼈를 이용한 공격을 한 번 흡수합니다."},aura={{28,164028067},"다음 뼈 공격 흡수"}}
