rows[114007]={title={{9,1564367309},"영혼의 불길"},description={{85,824038547},"자연 피해를 입히는 독한 눈물의 웅덩이를 만듭니다. 시간이 지날수록 커집니다."},aura={{85,824038547},"자연 피해를 입히는 독한 눈물의 웅덩이 생성\010시간이 지날수록 커짐"}}
