rows[115294]={title={{8,234283027},"마나 차"},description={"^restores ([%+%-]?%d[%d,.%+%-to –]*)%% of your maximum mana per stack of mana tea active%. mana tea must be channeled, lasting ([%+%-]?%d[%d,.%+%-to –]*) sec per stack%. cancelling the channel will not waste stacks%.$","마나 차 중첩 하나당 최대 마나의 \0311\031%를 회복합니다. 마나 차를 마시려면 중첩 하나당 \0312\031초 동안 정신 집중이 필요합니다. 정신 집중을 중단하면 마나 차 중첩은 소비되지 않습니다.",{0,0},{1,2}},aura={"^restoring ([%+%-]?%d[%d,.%+%-to –]*)%% mana every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031%의 마나 회복",{0,0},{1,2}}}
rows[115295]={title={{5,533427103},"방어 자세"},description={"^you guard against future attacks, absorbing ([%+%-]?%d[%d,.%+%-to –]*) damage for ([%+%-]?%d[%d,.]* %a+)%. any heals you apply to yourself while guarding are increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","공격에 대비해 방어 자세를 취합니다. \0312\031 동안 \0311\031의 피해를 흡수합니다.\010\010방어 자세를 취한 동안 자신을 스스로 치유하면 치유량이 \0313\031%만큼 증가합니다.",{0,1,0},{1,2,3}},aura={"^absorbing ([%+%-]?%d[%d,.%+%-to –]*) damage%. heals done to yourself are increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0311\031의 피해 흡수\010자신을 스스로 치유할 때 치유량 \0312\031%만큼 증가",{0,0},{1,2}}}
rows[115297]={title={{10,1021877755},"영혼 도려내기"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%. every time evict soul deals damage it creates an evicted soul of the target%. evicted souls will attack the closest target to them that did not create it%.$","\0313\031 동안 \0312\031초마다 \0311\031의 암흑 피해를 입힙니다. 도려낸 영혼이 피해를 입힐 때마다 대상의 영혼을 도려냅니다. 도려낸 영혼은 소환자가 아닌 가장 가까운 대상을 찾아 공격합니다.",{0,0,1},{1,2,3}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) shadow damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. creates an evicted soul every ([%+%-]?%d[%d,.%+%-to –]*) sec%.$","\0312\031초마다 \0311\031의 암흑 피해\010\0312\031초마다 도려낸 영혼 소환",{0,0,0},{1,2,2}}}
