rows[115310]={title={{7,1480736838},"재활"},description={"^instantly heals all party and raid members within ([%+%-]?%d[%d,.%+%-to –]*) yards for ([%+%-]?%d[%d,.%+%-to –]*), and clears them of any harmful magical, poison and disease effects%.$","반경 \0311\031미터 내에 있는 모든 파티원과 공격대원의 생명력을 \0312\031만큼 회복시키고 해로운 마법, 독, 질병 효과를 모두 제거합니다.",{0,0},{1,2}}}
rows[115311]={title={{17,1852067816},"괴력의 지팡이 강타"},description={"^you swing your staff onto the enemy dealing ([%+%-]?%d[%d,.%+%-to –]*)%% weapon damage%. you attack with such force that you take backlash damage equal to ([%+%-]?%d[%d,.%+%-to –]*)%% of the damage done%. if the backlash damage done to yourself is dodged or absorbed completely, you gain 2 dark force%.$","적에게 지팡이를 휘둘러 무기 공격력의 \0311\031%에 해당하는 피해를 입힙니다. 너무 힘껏 때린 나머지, 반동으로 인해 \0312\031%의 피해가 자신에게 돌아옵니다.\010\010반동 피해를 회피하거나 모두 흡수하면 2의 암공력을 얻습니다.",{0,0},{1,2}}}
